ITEMS.append({
 "id": "l43-ann-apagoreftiko", "title": "Απαγορευτικό απόπλου", "title_en": "Ferries banned from sailing", "type": "announcement", "level": "B2",
 "context_el": "Θα ακούσετε μια ανακοίνωση από τα μεγάφωνα στο λιμάνι του Πειραιά.",
 "script": [
  L("Εκφωνήτρια", "f", "Προσοχή, παρακαλώ. Λόγω των ισχυρών ανέμων, που φτάνουν τα εννέα μποφόρ στο Αιγαίο, το Λιμενικό έχει εκδώσει απαγορευτικό απόπλου για όλα τα πλοία προς τις Κυκλάδες και τα Δωδεκάνησα. Τα δρομολόγια της πρωινής ζώνης δεν θα πραγματοποιηθούν.", "Attention, please. Because of the strong winds, which are reaching force nine in the Aegean, the Coast Guard has issued a ban on sailing for all ships to the Cyclades and the Dodecanese. The morning sailings will not take place."),
  L("Εκφωνήτρια", "f", "Τα δρομολόγια προς τον Αργοσαρωνικό εκτελούνται κανονικά. Οι επιβάτες με εισιτήρια για τα δρομολόγια που ακυρώθηκαν μπορούν να τα αλλάξουν χωρίς χρέωση για οποιαδήποτε ημερομηνία μέσα στον επόμενο μήνα ή να ζητήσουν επιστροφή χρημάτων στα εκδοτήρια της Πύλης Ε7.", "Sailings to the Saronic Gulf islands are running normally. Passengers with tickets for the cancelled sailings can change them free of charge for any date within the next month or ask for a refund at the ticket offices at Gate E7."),
  L("Εκφωνήτρια", "f", "Σύμφωνα με την Εθνική Μετεωρολογική Υπηρεσία, οι άνεμοι αναμένεται να εξασθενήσουν από αύριο το απόγευμα. Η επόμενη ενημέρωση θα γίνει στις δώδεκα το μεσημέρι. Παρακαλούμε, πριν έρθετε στο λιμάνι, να επικοινωνείτε με την ακτοπλοϊκή σας εταιρεία.", "According to the National Meteorological Service, the winds are expected to weaken from tomorrow afternoon. The next update will be at twelve noon. Before coming to the port, please contact your ferry company."),
 ],
 "questions": [
  Q("Για ποιους προορισμούς ισχύει το απαγορευτικό απόπλου;", ["Για όλα τα νησιά της Ελλάδας", "Για τις Κυκλάδες και τα Δωδεκάνησα", "Μόνο για τον Αργοσαρωνικό", "Μόνο για την Κρήτη"], 1, "απαγορευτικό απόπλου για όλα τα πλοία προς τις Κυκλάδες και τα Δωδεκάνησα"),
  Q("Τι μπορούν να κάνουν οι επιβάτες με εισιτήρια για τα δρομολόγια που ακυρώθηκαν;", ["Να ταξιδέψουν με αεροπλάνο δωρεάν", "Να τα αλλάξουν χωρίς χρέωση ή να ζητήσουν επιστροφή χρημάτων", "Να περιμένουν στο πλοίο", "Να πάρουν κουπόνι για ξενοδοχείο"], 1, "μπορούν να τα αλλάξουν χωρίς χρέωση ... ή να ζητήσουν επιστροφή χρημάτων"),
  Q("Πότε αναμένεται να εξασθενήσουν οι άνεμοι;", ["Απόψε το βράδυ", "Από αύριο το απόγευμα", "Σε μία εβδομάδα", "Στις δώδεκα το μεσημέρι"], 1, "οι άνεμοι αναμένεται να εξασθενήσουν από αύριο το απόγευμα"),
 ],
 "gloss": {"μποφόρ": "μποφόρ — Beaufort (wind force)", "Λιμενικό": "Λιμενικό — Coast Guard", "εκδώσει": "εκδίδω — to issue", "απαγορευτικό απόπλου": "απαγορευτικό απόπλου — ban on ships leaving port", "δρομολόγια": "δρομολόγιο — (scheduled) sailing, route", "χρέωση": "χρέωση — charge", "επιστροφή χρημάτων": "επιστροφή χρημάτων — refund", "εκδοτήρια": "εκδοτήριο — ticket office", "εξασθενήσουν": "εξασθενώ — to weaken", "ακτοπλοϊκή": "ακτοπλοϊκός — coastal shipping (adj.)"},
})

ITEMS.append({
 "id": "l43-vm-diaxeiristis", "title": "Μήνυμα από τον διαχειριστή", "title_en": "A message from the building manager", "type": "voicemail", "level": "B2",
 "context_el": "Θα ακούσετε ένα μήνυμα από τον διαχειριστή της πολυκατοικίας σας στον τηλεφωνητή σας.",
 "script": [
  L("Διαχειριστής", "m", "Καλησπέρα, κυρία Αντωνίου, ο Στέλιος είμαι, ο διαχειριστής. Σας τηλεφωνώ για το ασανσέρ. Ο τεχνικός ήρθε σήμερα το πρωί και είπε ότι πρέπει να αλλάξει το μοτέρ, γιατί είναι πάνω από τριάντα χρονών και δεν βρίσκονται πια ανταλλακτικά.", "Good evening, Mrs Antoniou, it's Stelios, the building manager. I'm calling about the lift. The technician came this morning and said the motor has to be replaced, because it's over thirty years old and spare parts can't be found any more."),
  L("Διαχειριστής", "m", "Το κόστος είναι περίπου τέσσερις χιλιάδες ευρώ, που θα μοιραστεί σε όλα τα διαμερίσματα ανάλογα με τα χιλιοστά. Για εσάς, στον πέμπτο, θα είναι γύρω στα τριακόσια ευρώ. Μπορεί να πληρωθεί και σε τρεις δόσεις, μαζί με τα κοινόχρηστα.", "The cost is about four thousand euros, which will be divided among all the flats according to their shares. For you, on the fifth floor, it will be around three hundred euros. It can also be paid in three instalments, together with the service charges."),
  L("Διαχειριστής", "m", "Για να το αποφασίσουμε, κάνουμε γενική συνέλευση την Πέμπτη στις οχτώ το βράδυ, στην είσοδο της πολυκατοικίας. Αν δεν μπορείτε να έρθετε, μπορείτε να δώσετε εξουσιοδότηση σε κάποιον γείτονα. Μέχρι να γίνει η επισκευή, το ασανσέρ θα μείνει κλειστό. Συγγνώμη για την ταλαιπωρία.", "To decide on it, we're holding a general meeting on Thursday at eight in the evening, in the entrance of the building. If you can't come, you can authorise a neighbour. Until the repair is done, the lift will stay out of service. Sorry for the inconvenience."),
 ],
 "questions": [
  Q("Γιατί πρέπει να αλλάξει το μοτέρ του ασανσέρ;", ["Επειδή κάνει πολύ θόρυβο", "Επειδή είναι πολύ παλιό και δεν βρίσκονται ανταλλακτικά", "Επειδή το χάλασε ένας ένοικος", "Επειδή το απαιτεί ο νέος νόμος"], 1, "είναι πάνω από τριάντα χρονών και δεν βρίσκονται πια ανταλλακτικά"),
  Q("Πόσα θα πληρώσει περίπου η κυρία Αντωνίου;", ["Τέσσερις χιλιάδες ευρώ", "Γύρω στα τριακόσια ευρώ", "Εκατό ευρώ", "Τίποτα"], 1, "Για εσάς, στον πέμπτο, θα είναι γύρω στα τριακόσια ευρώ"),
  Q("Τι μπορεί να κάνει η κυρία Αντωνίου, αν δεν μπορεί να πάει στη συνέλευση;", ["Να στείλει email στον τεχνικό", "Να δώσει εξουσιοδότηση σε κάποιον γείτονα", "Να ψηφίσει τηλεφωνικά", "Να ζητήσει αναβολή"], 1, "μπορείτε να δώσετε εξουσιοδότηση σε κάποιον γείτονα"),
 ],
 "gloss": {"διαχειριστή": "διαχειριστής — building manager", "ασανσέρ": "ασανσέρ — lift, elevator", "μοτέρ": "μοτέρ — motor", "ανταλλακτικά": "ανταλλακτικό — spare part", "χιλιοστά": "χιλιοστά — (owner's) share in a building", "δόσεις": "δόση — instalment", "κοινόχρηστα": "κοινόχρηστα — building service charges", "γενική συνέλευση": "γενική συνέλευση — general meeting", "εξουσιοδότηση": "εξουσιοδότηση — authorisation, proxy", "ταλαιπωρία": "ταλαιπωρία — inconvenience"},
})

ITEMS.append({
 "id": "l43-dia-papoutsia", "title": "Λάθος νούμερο", "title_en": "The wrong size", "type": "dialogue", "level": "B2",
 "context_el": "Θα ακούσετε μια πελάτισσα που τηλεφωνεί στην εξυπηρέτηση πελατών ενός ηλεκτρονικού καταστήματος για ένα ζευγάρι παπούτσια.",
 "script": [
  L("Υπάλληλος", "m", "Εξυπηρέτηση πελατών, καλησπέρα σας. Πώς μπορώ να σας βοηθήσω;", "Customer service, good evening. How can I help you?"),
  L("Πελάτισσα", "f", "Καλησπέρα. Παρήγγειλα την περασμένη εβδομάδα ένα ζευγάρι μποτάκια, νούμερο τριάντα οχτώ, αλλά μου ήρθε τριάντα έξι. Και επιπλέον το κουτί ήταν σκισμένο. Θα ήθελα να τα αλλάξω.", "Good evening. Last week I ordered a pair of ankle boots, size thirty-eight, but I received thirty-six. And on top of that the box was torn. I'd like to exchange them."),
  L("Υπάλληλος", "m", "Λυπάμαι πολύ για το λάθος. Δυστυχώς, το τριάντα οχτώ σε αυτό το χρώμα έχει εξαντληθεί, αλλά υπάρχει σε μαύρο ή σε μπορντό. Αλλιώς, μπορούμε να σας επιστρέψουμε ολόκληρο το ποσό. Σε κάθε περίπτωση, ο κούριερ θα έρθει να παραλάβει τα παπούτσια από το σπίτι σας, χωρίς καμία χρέωση.", "I'm very sorry for the mistake. Unfortunately, the thirty-eight in this colour is sold out, but it's available in black or burgundy. Otherwise, we can refund you the full amount. Either way, the courier will come and collect the shoes from your home at no charge."),
  L("Πελάτισσα", "f", "Τα μαύρα θα τα πάρω. Μπορεί ο κούριερ να φέρει τα καινούργια και να πάρει τα παλιά την ίδια μέρα; Δουλεύω όλη μέρα και δεν θέλω να περιμένω δύο φορές.", "I'll take the black ones. Can the courier bring the new ones and take the old ones on the same day? I work all day and I don't want to wait twice."),
  L("Υπάλληλος", "m", "Βεβαίως. Θα γίνει ανταλλαγή επί τόπου, την Πέμπτη μεταξύ πέντε και οχτώ το απόγευμα. Και για την ταλαιπωρία, θα σας στείλουμε έναν εκπτωτικό κωδικό δέκα τοις εκατό για την επόμενη αγορά σας.", "Certainly. It will be an exchange on the spot, on Thursday between five and eight in the afternoon. And for the inconvenience, we'll send you a ten per cent discount code for your next purchase."),
 ],
 "questions": [
  Q("Ποιο ήταν το πρόβλημα με την παραγγελία;", ["Τα παπούτσια ήταν λερωμένα", "Ήρθε λάθος νούμερο και το κουτί ήταν σκισμένο", "Δεν ήρθε ποτέ", "Ήρθε λάθος χρώμα"], 1, "νούμερο τριάντα οχτώ, αλλά μου ήρθε τριάντα έξι. Και επιπλέον το κουτί ήταν σκισμένο"),
  Q("Γιατί θέλει η πελάτισσα να γίνουν όλα την ίδια μέρα;", ["Επειδή φεύγει ταξίδι", "Επειδή δουλεύει όλη μέρα και δεν θέλει να περιμένει δύο φορές", "Επειδή χρειάζεται τα παπούτσια για έναν γάμο", "Επειδή ο κούριερ αργεί πάντα"], 1, "Δουλεύω όλη μέρα και δεν θέλω να περιμένω δύο φορές"),
  Q("Τι θα της στείλει το κατάστημα για την ταλαιπωρία;", ["Ένα δεύτερο ζευγάρι δωρεάν", "Έναν εκπτωτικό κωδικό δέκα τοις εκατό", "Δωρεάν μεταφορικά για έναν χρόνο", "Μια δωροκάρτα πενήντα ευρώ"], 1, "θα σας στείλουμε έναν εκπτωτικό κωδικό δέκα τοις εκατό"),
 ],
 "gloss": {"εξυπηρέτηση πελατών": "εξυπηρέτηση πελατών — customer service", "Παρήγγειλα": "παραγγέλνω — to order", "μποτάκια": "μποτάκι — ankle boot", "νούμερο": "νούμερο — (shoe) size", "σκισμένο": "σκισμένος — torn", "έχει εξαντληθεί": "εξαντλούμαι — to be sold out", "μπορντό": "μπορντό — burgundy (colour)", "κούριερ": "κούριερ — courier", "επί τόπου": "επί τόπου — on the spot", "εκπτωτικό κωδικό": "εκπτωτικός κωδικός — discount code"},
})

ITEMS.append({
 "id": "l43-dia-syntaxiodotisi", "title": "Αποχαιρετισμός σε μια συνάδελφο", "title_en": "A farewell for a colleague", "type": "dialogue", "level": "B2",
 "context_el": "Θα ακούσετε δύο συναδέλφους που οργανώνουν το αποχαιρετιστήριο πάρτι για μια συνάδελφο που βγαίνει στη σύνταξη.",
 "script": [
  L("Γιώργος", "m", "Η κυρία Ελπίδα φεύγει στο τέλος του μήνα, μετά από τριάντα οχτώ χρόνια στην εταιρεία. Πρέπει να της κάνουμε κάτι ξεχωριστό. Σκέφτηκα να κλείσουμε ένα τραπέζι σε μια ταβέρνα την Παρασκευή το βράδυ.", "Mrs Elpida is leaving at the end of the month, after thirty-eight years with the company. We have to do something special for her. I thought we could book a table at a tavern on Friday evening."),
  L("Δέσποινα", "f", "Την Παρασκευή το βράδυ δεν θα έρθει κανείς, όλοι έχουν οικογένειες. Καλύτερα να το κάνουμε εδώ, στο γραφείο, την τελευταία της μέρα, στις δύο. Θα παραγγείλουμε φαγητό και θα φέρει ο καθένας κάτι γλυκό.", "Nobody will come on a Friday evening, everyone has families. Better to do it here, at the office, on her last day, at two. We'll order food and everyone will bring something sweet."),
  L("Γιώργος", "m", "Εντάξει, έχεις δίκιο. Και για δώρο; Μαζεύουμε από είκοσι ευρώ ο καθένας, όπως πέρσι για τον κύριο Μανώλη;", "OK, you're right. And for a present? Shall we collect twenty euros each, like last year for Mr Manolis?"),
  L("Δέσποινα", "f", "Ναι. Ξέρω ότι θέλει να ασχοληθεί με την κηπουρική, γιατί έχει ένα σπίτι στο χωριό. Θα της πάρουμε εργαλεία κήπου και μερικά φυτά. Κι εγώ θα μαζέψω φωτογραφίες απ' όλα αυτά τα χρόνια και θα φτιάξω ένα βίντεο. Μόνο να μην το μάθει από πριν. Μην πεις τίποτα στη Ρούλα, που δεν κρατάει μυστικό!", "Yes. I know she wants to take up gardening, because she has a house in the village. We'll get her garden tools and some plants. And I'll collect photos from all these years and make a video. Just don't let her find out beforehand. Don't say anything to Roula, who can't keep a secret!"),
 ],
 "questions": [
  Q("Γιατί η Δέσποινα δεν θέλει το πάρτι την Παρασκευή το βράδυ;", ["Επειδή η ταβέρνα είναι κλειστή", "Επειδή πιστεύει ότι δεν θα έρθει κανείς", "Επειδή η κυρία Ελπίδα δεν τρώει έξω", "Επειδή είναι ακριβό"], 1, "Την Παρασκευή το βράδυ δεν θα έρθει κανείς, όλοι έχουν οικογένειες"),
  Q("Γιατί θα της πάρουν εργαλεία κήπου;", ["Επειδή της χάλασαν τα δικά της", "Επειδή θέλει να ασχοληθεί με την κηπουρική στο σπίτι του χωριού", "Επειδή τα ζήτησε η ίδια", "Επειδή είναι φθηνά"], 1, "θέλει να ασχοληθεί με την κηπουρική, γιατί έχει ένα σπίτι στο χωριό"),
  Q("Γιατί δεν πρέπει να μάθει τίποτα η Ρούλα;", ["Επειδή δεν θα έρθει στο πάρτι", "Επειδή δεν κρατάει μυστικό", "Επειδή δεν συμπαθεί την κυρία Ελπίδα", "Επειδή δεν θέλει να πληρώσει"], 1, "Μην πεις τίποτα στη Ρούλα, που δεν κρατάει μυστικό"),
 ],
 "gloss": {"συναδέλφους": "συνάδελφος — colleague", "αποχαιρετιστήριο": "αποχαιρετιστήριος — farewell (adj.)", "βγαίνει στη σύνταξη": "βγαίνω στη σύνταξη — to retire", "ξεχωριστό": "ξεχωριστός — special", "να κλείσουμε": "κλείνω (τραπέζι) — to book (a table)", "παραγγείλουμε": "παραγγέλνω — to order", "Μαζεύουμε": "μαζεύω — to collect", "να ασχοληθεί": "ασχολούμαι με — to take up, be busy with", "κηπουρική": "κηπουρική — gardening", "μυστικό": "μυστικό — secret"},
})

ITEMS.append({
 "id": "l43-mono-sygkatoikisi", "title": "Τέσσερις σε ένα διαμέρισμα", "title_en": "Four in one flat", "type": "monologue", "level": "B2",
 "context_el": "Θα ακούσετε έναν φοιτητή που μιλάει σε ένα podcast για τη συγκατοίκηση με άλλους τρεις φοιτητές.",
 "script": [
  L("Άρης", "m", "Όταν ήρθα στη Θεσσαλονίκη για σπουδές, τα ενοίκια ήταν τόσο ψηλά, που ήταν αδύνατο να νοικιάσω μόνος μου ένα διαμέρισμα. Έτσι βρέθηκα σε ένα τριάρι στην Άνω Πόλη με άλλους τρεις φοιτητές, που δεν γνώριζα καθόλου: μια φοιτήτρια ιατρικής από την Κρήτη, έναν Ιταλό του Erasmus και έναν μουσικό από τη Λάρισα.", "When I came to Thessaloniki to study, rents were so high that it was impossible to rent a flat on my own. So I ended up in a three-room flat in the Upper Town with three other students I didn't know at all: a medical student from Crete, an Italian on Erasmus and a musician from Larissa."),
  L("Άρης", "m", "Τους πρώτους μήνες είχαμε πολλές εντάσεις. Ο μουσικός έκανε πρόβες με την κιθάρα του τα μεσάνυχτα, η φοιτήτρια ιατρικής διάβαζε για εξετάσεις και ήθελε απόλυτη ησυχία, και κανείς δεν έπλενε τα πιάτα του. Κάποια στιγμή καθίσαμε και γράψαμε κανόνες: πρόγραμμα καθαριότητας, ώρες ησυχίας και ένα κοινό ταμείο για τα βασικά, όπως το απορρυπαντικό και το χαρτί υγείας.", "In the first months we had a lot of tension. The musician rehearsed with his guitar at midnight, the medical student was studying for exams and wanted total quiet, and nobody washed their dishes. At some point we sat down and wrote rules: a cleaning rota, quiet hours and a shared kitty for basics, like detergent and toilet paper."),
  L("Άρης", "m", "Από τότε τα πράγματα άλλαξαν. Τρώμε μαζί τις Κυριακές, και ο καθένας μαγειρεύει κάτι από τον τόπο του. Ο Ιταλός μάς έμαθε να φτιάχνουμε σωστό ριζότο, κι εμείς τον μάθαμε να χορεύει τσάμικο. Νόμιζα ότι η συγκατοίκηση θα ήταν απλώς μια οικονομική λύση. Τελικά, απέκτησα τρεις φίλους για όλη μου τη ζωή.", "Since then things have changed. We eat together on Sundays, and each of us cooks something from home. The Italian taught us to make a proper risotto, and we taught him to dance the tsamikos. I thought flat-sharing would just be an economic solution. In the end, I gained three friends for life."),
 ],
 "questions": [
  Q("Γιατί ο Άρης αποφάσισε να μείνει με άλλους φοιτητές;", ["Επειδή φοβόταν να μένει μόνος", "Επειδή τα ενοίκια ήταν πολύ ψηλά", "Επειδή το ζήτησαν οι γονείς του", "Επειδή ήξερε ήδη τους συγκατοίκους"], 1, "τα ενοίκια ήταν τόσο ψηλά, που ήταν αδύνατο να νοικιάσω μόνος μου ένα διαμέρισμα"),
  Q("Πώς έλυσαν τις εντάσεις των πρώτων μηνών;", ["Ο μουσικός έφυγε από το σπίτι", "Έγραψαν κανόνες για την καθαριότητα, την ησυχία και τα κοινά έξοδα", "Ζήτησαν βοήθεια από τον ιδιοκτήτη", "Χώρισαν το ψυγείο στα τέσσερα"], 1, "καθίσαμε και γράψαμε κανόνες: πρόγραμμα καθαριότητας, ώρες ησυχίας και ένα κοινό ταμείο"),
  Q("Τι κατάλαβε τελικά ο Άρης για τη συγκατοίκηση;", ["Ότι είναι μόνο μια οικονομική λύση", "Ότι του χάρισε τρεις φίλους για όλη του τη ζωή", "Ότι θέλει να μείνει μόνος του", "Ότι είναι πολύ κουραστική"], 1, "Τελικά, απέκτησα τρεις φίλους για όλη μου τη ζωή"),
 ],
 "gloss": {"συγκατοίκηση": "συγκατοίκηση — flat-sharing", "ενοίκια": "ενοίκιο — rent", "τριάρι": "τριάρι — three-room flat", "εντάσεις": "ένταση — tension", "πρόβες": "πρόβα — rehearsal", "απόλυτη ησυχία": "απόλυτη ησυχία — total quiet", "καθαριότητας": "καθαριότητα — cleaning", "κοινό ταμείο": "κοινό ταμείο — shared kitty", "απορρυπαντικό": "απορρυπαντικό — detergent", "τσάμικο": "τσάμικος — tsamikos (Greek folk dance)"},
})

ITEMS.append({
 "id": "l43-rep-apergia", "title": "Απεργία στα μέσα μεταφοράς", "title_en": "A public transport strike", "type": "report", "level": "B2",
 "context_el": "Θα ακούσετε ένα ρεπορτάζ στο δελτίο ειδήσεων για μια απεργία στα μέσα μαζικής μεταφοράς της Αθήνας.",
 "script": [
  L("Δημοσιογράφος", "f", "Χωρίς μετρό, ηλεκτρικό και τραμ θα μείνει αύριο η Αθήνα, καθώς οι εργαζόμενοι στα μέσα σταθερής τροχιάς κατεβαίνουν σε εικοσιτετράωρη απεργία. Τα λεωφορεία και τα τρόλεϊ θα κινούνται κανονικά, αλλά αναμένεται μεγάλος συνωστισμός, ιδίως τις πρωινές ώρες.", "Athens will be without the metro, the electric railway and the tram tomorrow, as workers on the rail-based services go on a twenty-four-hour strike. Buses and trolleybuses will run normally, but heavy crowding is expected, especially in the morning hours."),
  L("Δημοσιογράφος", "f", "Οι εργαζόμενοι διαμαρτύρονται για τις ελλείψεις προσωπικού, που, όπως λένε, οδηγούν σε εξαντλητικές βάρδιες, καθώς και για την καθυστέρηση στη συντήρηση των συρμών. Το υπουργείο Μεταφορών απαντά ότι έχουν ήδη προκηρυχθεί προσλήψεις και ότι νέοι συρμοί θα παραδοθούν μέσα στον επόμενο χρόνο.", "The workers are protesting about staff shortages, which they say lead to exhausting shifts, as well as about the delay in maintaining the trains. The Ministry of Transport replies that recruitment has already been announced and that new trains will be delivered within the next year."),
  L("Δημοσιογράφος", "f", "Η Τροχαία προειδοποιεί για αυξημένη κίνηση στους κεντρικούς δρόμους και συνιστά σε όσους μπορούν να εργαστούν από το σπίτι. Ο Διεθνής Αερολιμένας εξυπηρετείται μόνο με λεωφορεία εξπρές και ταξί, οπότε οι ταξιδιώτες καλό είναι να ξεκινήσουν νωρίτερα από το συνηθισμένο.", "The Traffic Police warn of increased traffic on the main roads and advise those who can to work from home. The International Airport will be served only by express buses and taxis, so travellers would do well to set off earlier than usual."),
 ],
 "questions": [
  Q("Ποια μέσα θα κινούνται αύριο κανονικά;", ["Το μετρό και το τραμ", "Τα λεωφορεία και τα τρόλεϊ", "Μόνο ο ηλεκτρικός", "Κανένα μέσο"], 1, "Τα λεωφορεία και τα τρόλεϊ θα κινούνται κανονικά"),
  Q("Για ποιον λόγο διαμαρτύρονται οι εργαζόμενοι;", ["Για τις τιμές των εισιτηρίων", "Για τις ελλείψεις προσωπικού και την καθυστέρηση στη συντήρηση", "Για τα νέα δρομολόγια", "Για την ασφάλεια των επιβατών τη νύχτα"], 1, "διαμαρτύρονται για τις ελλείψεις προσωπικού ... καθώς και για την καθυστέρηση στη συντήρηση των συρμών"),
  Q("Τι συνιστά η Τροχαία;", ["Να χρησιμοποιούν όλοι ποδήλατο", "Να εργαστούν από το σπίτι όσοι μπορούν", "Να μη βγει κανείς από το σπίτι", "Να πάνε όλοι νωρίτερα στη δουλειά"], 1, "συνιστά σε όσους μπορούν να εργαστούν από το σπίτι"),
 ],
 "gloss": {"απεργία": "απεργία — strike", "σταθερής τροχιάς": "μέσα σταθερής τροχιάς — rail-based transport", "εικοσιτετράωρη": "εικοσιτετράωρος — twenty-four-hour", "συνωστισμός": "συνωστισμός — crowding", "ελλείψεις προσωπικού": "έλλειψη προσωπικού — staff shortage", "εξαντλητικές": "εξαντλητικός — exhausting", "βάρδιες": "βάρδια — shift", "συρμών": "συρμός — train (set of carriages)", "προκηρυχθεί": "προκηρύσσομαι — to be announced (of a competition, hiring)", "Τροχαία": "Τροχαία — Traffic Police"},
})

ITEMS.append({
 "id": "l43-rep-agriogourouna", "title": "Αγριογούρουνα στα προάστια", "title_en": "Wild boars in the suburbs", "type": "report", "level": "B2",
 "context_el": "Θα ακούσετε ένα ρεπορτάζ για τα αγριογούρουνα που εμφανίζονται όλο και πιο συχνά στις γειτονιές των βόρειων προαστίων.",
 "script": [
  L("Δημοσιογράφος", "m", "Τρίτη τα ξημερώματα στην Πεντέλη: μια οικογένεια αγριογούρουνων, μια μητέρα με πέντε μικρά, ψάχνει τροφή στους κάδους σκουπιδιών, λίγα μέτρα από μια παιδική χαρά. Οι κάτοικοι λένε ότι τέτοιες εικόνες έχουν γίνει πια καθημερινές.", "Tuesday at dawn in Penteli: a family of wild boars, a mother with five young, is looking for food in the rubbish bins, a few metres from a playground. Residents say that such scenes have now become an everyday sight."),
  L("Δημοσιογράφος", "m", "Σύμφωνα με τους ειδικούς, η αύξηση οφείλεται κυρίως σε δύο λόγους. Πρώτον, οι πυρκαγιές των τελευταίων ετών κατέστρεψαν μεγάλο μέρος του φυσικού τους χώρου. Δεύτερον, οι πόλεις τούς προσφέρουν εύκολη τροφή: ανοιχτούς κάδους, φρούτα στους κήπους, ακόμα και φαγητό που αφήνουν ορισμένοι για τις αδέσποτες γάτες.", "According to experts, the increase is mainly due to two reasons. First, the fires of recent years destroyed a large part of their natural habitat. Second, the towns offer them easy food: open bins, fruit in gardens, even food some people leave out for stray cats."),
  L("Δημοσιογράφος", "m", "Τα αγριογούρουνα σπάνια επιτίθενται σε ανθρώπους, αλλά μπορεί να γίνουν επιθετικά, αν νιώσουν ότι απειλούνται τα μικρά τους. Οι ειδικοί συμβουλεύουν να μην τα πλησιάζουμε και να μην τα ταΐζουμε ποτέ. Ο δήμος, από την πλευρά του, θα τοποθετήσει κάδους που κλειδώνουν και θα συνεργαστεί με το Δασαρχείο για τη μεταφορά τους σε ορεινές περιοχές.", "Wild boars rarely attack people, but they can become aggressive if they feel their young are threatened. Experts advise us not to approach them and never to feed them. The municipality, for its part, will install bins that lock and will work with the Forestry Service to move them to mountain areas."),
 ],
 "questions": [
  Q("Πού βρήκε ο δημοσιογράφος την οικογένεια αγριογούρουνων;", ["Μέσα σε ένα σχολείο", "Στους κάδους σκουπιδιών κοντά σε μια παιδική χαρά", "Σε ένα χωράφι", "Στο κέντρο της Αθήνας"], 1, "ψάχνει τροφή στους κάδους σκουπιδιών, λίγα μέτρα από μια παιδική χαρά"),
  Q("Ποιοι είναι οι δύο λόγοι της αύξησης, κατά τους ειδικούς;", ["Ο ήπιος χειμώνας και το κυνήγι", "Οι πυρκαγιές και η εύκολη τροφή στις πόλεις", "Οι νέοι δρόμοι και ο θόρυβος", "Η ξηρασία και οι αρρώστιες"], 1, "οι πυρκαγιές των τελευταίων ετών κατέστρεψαν μεγάλο μέρος του φυσικού τους χώρου ... οι πόλεις τούς προσφέρουν εύκολη τροφή"),
  Q("Πότε μπορεί να γίνουν επιθετικά τα αγριογούρουνα;", ["Όταν πεινάνε", "Όταν νιώσουν ότι απειλούνται τα μικρά τους", "Τη νύχτα", "Όταν βρέχει"], 1, "μπορεί να γίνουν επιθετικά, αν νιώσουν ότι απειλούνται τα μικρά τους"),
 ],
 "gloss": {"αγριογούρουνα": "αγριογούρουνο — wild boar", "προαστίων": "προάστιο — suburb", "ξημερώματα": "ξημερώματα — dawn", "κάδους σκουπιδιών": "κάδος σκουπιδιών — rubbish bin", "πυρκαγιές": "πυρκαγιά — (wild)fire", "φυσικού τους χώρου": "φυσικός χώρος — natural habitat", "αδέσποτες": "αδέσποτος — stray", "επιτίθενται": "επιτίθεμαι — to attack", "επιθετικά": "επιθετικός — aggressive", "Δασαρχείο": "Δασαρχείο — Forestry Service"},
})

ITEMS.append({
 "id": "l43-int-eikonografos", "title": "Μια εικονογράφος παιδικών βιβλίων", "title_en": "An illustrator of children's books", "type": "interview", "level": "B2",
 "context_el": "Θα ακούσετε μια συνέντευξη με μια εικονογράφο παιδικών βιβλίων σε μια ραδιοφωνική εκπομπή για τον πολιτισμό.",
 "script": [
  L("Δημοσιογράφος", "m", "Έχετε εικονογραφήσει πάνω από εξήντα παιδικά βιβλία. Πώς ξεκινάτε, όταν σας δίνουν ένα καινούργιο κείμενο;", "You have illustrated more than sixty children's books. How do you start when you're given a new text?"),
  L("Εικονογράφος", "f", "Το διαβάζω πολλές φορές, φωναχτά, σαν να το διαβάζω σε ένα παιδί. Έτσι καταλαβαίνω πού σταματάει η ανάσα και πού χρειάζεται μια εικόνα. Μετά κάνω πολλά μικρά σκίτσα με μολύβι, και μόνο όταν βρω τους χαρακτήρες περνάω στα χρώματα. Δουλεύω ακόμα με ακουαρέλα, όχι στον υπολογιστή.", "I read it many times, out loud, as if I were reading it to a child. That way I understand where the breath stops and where an image is needed. Then I make lots of little pencil sketches, and only when I've found the characters do I move on to colour. I still work in watercolour, not on the computer."),
  L("Δημοσιογράφος", "m", "Η εικόνα πρέπει να λέει το ίδιο με το κείμενο;", "Should the picture say the same as the text?"),
  L("Εικονογράφος", "f", "Κάθε άλλο. Αν η εικόνα επαναλαμβάνει το κείμενο, είναι περιττή. Μου αρέσει να κρύβω μικρές ιστορίες που δεν γράφονται πουθενά: μια γάτα που εμφανίζεται σε κάθε σελίδα, ένα παράθυρο όπου κάτι αλλάζει. Τα παιδιά τα βρίσκουν πάντα, πολύ πριν από τους μεγάλους. Μου γράφουν γράμματα για να μου πουν τι ανακάλυψαν, και αυτά τα γράμματα είναι η μεγαλύτερη ανταμοιβή μου.", "Quite the opposite. If the picture repeats the text, it's unnecessary. I like to hide little stories that aren't written anywhere: a cat that appears on every page, a window where something changes. Children always find them, long before the grown-ups. They write me letters to tell me what they discovered, and those letters are my greatest reward."),
 ],
 "questions": [
  Q("Πώς ξεκινάει η εικονογράφος τη δουλειά σε ένα καινούργιο βιβλίο;", ["Ζωγραφίζει αμέσως με χρώματα", "Διαβάζει το κείμενο φωναχτά πολλές φορές", "Μιλάει με τον εκδότη", "Ψάχνει εικόνες στο διαδίκτυο"], 1, "Το διαβάζω πολλές φορές, φωναχτά, σαν να το διαβάζω σε ένα παιδί"),
  Q("Γιατί, κατά την εικονογράφο, η εικόνα δεν πρέπει να επαναλαμβάνει το κείμενο;", ["Επειδή τα παιδιά δεν διαβάζουν", "Επειδή τότε είναι περιττή", "Επειδή το απαγορεύουν οι εκδότες", "Επειδή κοστίζει περισσότερο"], 1, "Αν η εικόνα επαναλαμβάνει το κείμενο, είναι περιττή"),
  Q("Ποια είναι η μεγαλύτερη ανταμοιβή της;", ["Τα βραβεία", "Τα γράμματα των παιδιών για όσα ανακάλυψαν", "Οι πωλήσεις των βιβλίων", "Οι εκθέσεις της"], 1, "αυτά τα γράμματα είναι η μεγαλύτερη ανταμοιβή μου"),
 ],
 "gloss": {"εικονογράφο": "εικονογράφος — illustrator", "εικονογραφήσει": "εικονογραφώ — to illustrate", "φωναχτά": "φωναχτά — out loud", "ανάσα": "ανάσα — breath", "σκίτσα": "σκίτσο — sketch", "χαρακτήρες": "χαρακτήρας — character", "ακουαρέλα": "ακουαρέλα — watercolour", "Κάθε άλλο": "κάθε άλλο — quite the opposite", "περιττή": "περιττός — unnecessary", "ανταμοιβή": "ανταμοιβή — reward"},
})

ITEMS.append({
 "id": "l43-mono-tetraimeri", "title": "Τέσσερις μέρες δουλειά την εβδομάδα;", "title_en": "A four-day working week?", "type": "monologue", "level": "C1",
 "context_el": "Θα ακούσετε μια οικονομολόγο που μιλάει σε ένα συνέδριο για την τετραήμερη εργασία.",
 "script": [
  L("Οικονομολόγος", "f", "Η ιδέα ότι θα μπορούσαμε να δουλεύουμε τέσσερις μέρες την εβδομάδα χωρίς μείωση μισθού ακούγεται σε πολλούς ουτοπική. Ας θυμηθούμε, ωστόσο, ότι και το οχτάωρο, όταν διεκδικήθηκε τον δέκατο ένατο αιώνα, θεωρούνταν οικονομική αυτοκτονία. Η διάρκεια της εργάσιμης εβδομάδας δεν είναι φυσικός νόμος· είναι κοινωνική σύμβαση, και οι συμβάσεις αλλάζουν.", "The idea that we could work four days a week without a pay cut sounds utopian to many. Let us remember, however, that the eight-hour day, too, when it was demanded in the nineteenth century, was considered economic suicide. The length of the working week is not a law of nature; it is a social convention, and conventions change."),
  L("Οικονομολόγος", "f", "Τα πιλοτικά προγράμματα των τελευταίων ετών, σε χώρες όπως το Ηνωμένο Βασίλειο και η Ισλανδία, έδωσαν ενθαρρυντικά αποτελέσματα. Στις περισσότερες επιχειρήσεις που συμμετείχαν, η παραγωγικότητα διατηρήθηκε ή και αυξήθηκε, ενώ μειώθηκαν οι απουσίες λόγω ασθένειας και οι παραιτήσεις. Οι εργαζόμενοι ανέφεραν λιγότερο άγχος και περισσότερο χρόνο για την οικογένεια.", "The pilot schemes of recent years, in countries such as the United Kingdom and Iceland, gave encouraging results. In most of the companies that took part, productivity was maintained or even increased, while sick leave and resignations fell. Workers reported less stress and more time for their families."),
  L("Οικονομολόγος", "f", "Πρέπει όμως να είμαστε προσεκτικοί με τις γενικεύσεις. Οι επιχειρήσεις που δέχτηκαν να συμμετάσχουν ήταν, ως επί το πλείστον, γραφεία με εργασίες γνώσης, όπου ο χρόνος μπορεί να αναδιοργανωθεί με την κατάργηση περιττών συσκέψεων. Σε ένα νοσοκομείο, σε ένα σχολείο ή σε ένα εργοστάσιο, η μείωση των ωρών σημαίνει ότι χρειάζεται περισσότερο προσωπικό, άρα και μεγαλύτερο κόστος.", "But we must be careful with generalisations. The companies that agreed to take part were, for the most part, offices doing knowledge work, where time can be reorganised by cutting unnecessary meetings. In a hospital, a school or a factory, reducing hours means more staff are needed, and therefore higher costs."),
  L("Οικονομολόγος", "f", "Το ερώτημα, λοιπόν, δεν είναι αν η τετραήμερη εργασία «λειτουργεί» γενικά, αλλά για ποιους, υπό ποιες προϋποθέσεις και ποιος θα επωμιστεί το κόστος της μετάβασης. Αν δεν απαντήσουμε σε αυτά, κινδυνεύουμε να δημιουργήσουμε μια αγορά εργασίας δύο ταχυτήτων: μια προνομιούχα μειοψηφία με τριήμερα Σαββατοκύριακα και μια πλειονότητα που θα συνεχίζει όπως πριν.", "The question, then, is not whether the four-day week 'works' in general, but for whom, under what conditions, and who will bear the cost of the transition. If we don't answer these, we risk creating a two-speed labour market: a privileged minority with three-day weekends and a majority that carries on as before."),
 ],
 "questions": [
  Q("Γιατί η ομιλήτρια αναφέρεται στο οχτάωρο;", ["Για να δείξει ότι το οχτάωρο είναι ξεπερασμένο", "Για να δείξει ότι και αυτό θεωρούνταν κάποτε ουτοπικό", "Για να υποστηρίξει ότι δεν πρέπει να αλλάξει τίποτα", "Για να εξηγήσει την ιστορία των συνδικάτων"], 1, "και το οχτάωρο, όταν διεκδικήθηκε τον δέκατο ένατο αιώνα, θεωρούνταν οικονομική αυτοκτονία"),
  Q("Τι έδειξαν τα πιλοτικά προγράμματα στις περισσότερες επιχειρήσεις;", ["Ότι η παραγωγικότητα έπεσε σημαντικά", "Ότι η παραγωγικότητα διατηρήθηκε ή αυξήθηκε και μειώθηκαν οι απουσίες", "Ότι οι εργαζόμενοι ήθελαν να επιστρέψουν στις πέντε μέρες", "Ότι αυξήθηκαν οι παραιτήσεις"], 1, "η παραγωγικότητα διατηρήθηκε ή και αυξήθηκε, ενώ μειώθηκαν οι απουσίες λόγω ασθένειας"),
  Q("Γιατί, κατά την ομιλήτρια, πρέπει να είμαστε προσεκτικοί με τις γενικεύσεις;", ["Επειδή τα προγράμματα κράτησαν λίγο", "Επειδή συμμετείχαν κυρίως γραφεία, ενώ σε άλλους χώρους η μείωση ωρών απαιτεί περισσότερο προσωπικό", "Επειδή τα αποτελέσματα ήταν ψεύτικα", "Επειδή οι εργαζόμενοι δεν ρωτήθηκαν"], 1, "Οι επιχειρήσεις που δέχτηκαν να συμμετάσχουν ήταν, ως επί το πλείστον, γραφεία με εργασίες γνώσης"),
  Q("Ποιον κίνδυνο βλέπει η ομιλήτρια;", ["Την αύξηση της ανεργίας", "Μια αγορά εργασίας δύο ταχυτήτων", "Την κατάρρευση του τουρισμού", "Τη μείωση των μισθών για όλους"], 1, "κινδυνεύουμε να δημιουργήσουμε μια αγορά εργασίας δύο ταχυτήτων"),
 ],
 "gloss": {"τετραήμερη": "τετραήμερος — four-day", "ουτοπική": "ουτοπικός — utopian", "οχτάωρο": "οχτάωρο — eight-hour working day", "διεκδικήθηκε": "διεκδικούμαι — to be demanded, claimed", "κοινωνική σύμβαση": "κοινωνική σύμβαση — social convention", "πιλοτικά": "πιλοτικός — pilot (adj.)", "ενθαρρυντικά": "ενθαρρυντικός — encouraging", "παραιτήσεις": "παραίτηση — resignation", "ως επί το πλείστον": "ως επί το πλείστον — for the most part", "συσκέψεων": "σύσκεψη — meeting", "θα επωμιστεί": "επωμίζομαι — to bear, shoulder", "μετάβασης": "μετάβαση — transition", "δύο ταχυτήτων": "δύο ταχυτήτων — two-speed", "προνομιούχα": "προνομιούχος — privileged", "μειοψηφία": "μειοψηφία — minority"},
})

ITEMS.append({
 "id": "l43-int-diglossia", "title": "Μεγαλώνοντας με δύο γλώσσες", "title_en": "Growing up with two languages", "type": "interview", "level": "C1",
 "context_el": "Θα ακούσετε μια συνέντευξη με μια γλωσσολόγο που ερευνά την ανάπτυξη των δίγλωσσων παιδιών.",
 "script": [
  L("Δημοσιογράφος", "m", "Πολλοί γονείς φοβούνται ότι, αν μιλούν στο παιδί τους δύο γλώσσες, θα το μπερδέψουν ή θα καθυστερήσει να μιλήσει. Έχουν βάση αυτοί οι φόβοι;", "Many parents fear that if they speak two languages to their child, they will confuse it or it will be late to talk. Are these fears well founded?"),
  L("Γλωσσολόγος", "f", "Είναι από τους πιο διαδεδομένους μύθους. Οι έρευνες δείχνουν ότι τα δίγλωσσα παιδιά περνούν τα ίδια αναπτυξιακά στάδια με τα μονόγλωσσα, περίπου στις ίδιες ηλικίες. Μπορεί σε κάποια φάση να έχουν λίγο μικρότερο λεξιλόγιο σε καθεμία γλώσσα χωριστά, αλλά, αν μετρήσουμε όλες τις λέξεις που ξέρουν και στις δύο, το συνολικό λεξιλόγιο είναι συνήθως ίσο ή και μεγαλύτερο.", "It's one of the most widespread myths. Research shows that bilingual children go through the same developmental stages as monolingual ones, at roughly the same ages. At some stage they may have a slightly smaller vocabulary in each language separately, but if we count all the words they know in both, the total vocabulary is usually equal or even larger."),
  L("Δημοσιογράφος", "m", "Και όταν ένα παιδί ανακατεύει τις γλώσσες μέσα στην ίδια πρόταση; Δεν είναι σημάδι σύγχυσης;", "And when a child mixes the languages within the same sentence? Isn't that a sign of confusion?"),
  L("Γλωσσολόγος", "f", "Κάθε άλλο. Η εναλλαγή κωδίκων, όπως τη λέμε, είναι φυσιολογική και συχνά πολύ εκλεπτυσμένη. Τα παιδιά δεν ανακατεύουν τις γλώσσες στην τύχη: το κάνουν κυρίως με συνομιλητές που ξέρουν ότι καταλαβαίνουν και τις δύο, και ακολουθούν γραμματικούς κανόνες. Με τη γιαγιά που μιλάει μόνο ελληνικά, τα ίδια παιδιά μιλούν μόνο ελληνικά. Αυτό δείχνει όχι σύγχυση, αλλά μια εντυπωσιακή επίγνωση του κοινωνικού πλαισίου.", "Quite the opposite. Code-switching, as we call it, is normal and often very sophisticated. Children don't mix languages at random: they do it mainly with speakers they know understand both, and they follow grammatical rules. With a grandmother who speaks only Greek, the same children speak only Greek. That shows not confusion, but an impressive awareness of the social context."),
  L("Δημοσιογράφος", "m", "Τι θα συμβουλεύατε τις οικογένειες μεταναστών που θέλουν να διατηρήσουν τη γλώσσα τους;", "What would you advise migrant families who want to keep their language?"),
  L("Γλωσσολόγος", "f", "Το μεγαλύτερο εμπόδιο δεν είναι γνωστικό αλλά κοινωνικό. Όταν η γλώσσα της οικογένειας δεν έχει κύρος στο σχολείο ή στη γειτονιά, τα παιδιά συχνά αρχίζουν να την αρνούνται γύρω στην εφηβεία. Γι' αυτό συμβουλεύω να μη συνδέεται η γλώσσα μόνο με υποχρεώσεις, αλλά με χαρά: τραγούδια, παιχνίδια, ταξίδια, φίλους της ίδιας ηλικίας. Μια γλώσσα επιβιώνει όταν το παιδί τη χρειάζεται για να ζήσει κάτι που αγαπά.", "The biggest obstacle is not cognitive but social. When the family's language has no prestige at school or in the neighbourhood, children often start rejecting it around adolescence. That's why I advise not to link the language only with obligations, but with joy: songs, games, trips, friends of the same age. A language survives when the child needs it to experience something it loves."),
 ],
 "questions": [
  Q("Τι δείχνουν οι έρευνες για την ανάπτυξη των δίγλωσσων παιδιών;", ["Ότι αργούν πάντα να μιλήσουν", "Ότι περνούν τα ίδια στάδια με τα μονόγλωσσα, περίπου στις ίδιες ηλικίες", "Ότι μαθαίνουν πιο γρήγορα να διαβάζουν", "Ότι ξεχνούν τη μία γλώσσα"], 1, "τα δίγλωσσα παιδιά περνούν τα ίδια αναπτυξιακά στάδια με τα μονόγλωσσα, περίπου στις ίδιες ηλικίες"),
  Q("Τι ισχύει για το συνολικό λεξιλόγιο των δίγλωσσων παιδιών;", ["Είναι πάντα μικρότερο", "Είναι συνήθως ίσο ή και μεγαλύτερο από των μονόγλωσσων", "Δεν μπορεί να μετρηθεί", "Είναι το μισό σε κάθε γλώσσα"], 1, "το συνολικό λεξιλόγιο είναι συνήθως ίσο ή και μεγαλύτερο"),
  Q("Τι δείχνει, κατά τη γλωσσολόγο, η εναλλαγή κωδίκων;", ["Ότι το παιδί δεν ξέρει καλά καμία γλώσσα", "Επίγνωση του κοινωνικού πλαισίου", "Ότι οι γονείς κάνουν λάθη", "Ότι το παιδί χρειάζεται λογοθεραπεία"], 1, "Αυτό δείχνει όχι σύγχυση, αλλά μια εντυπωσιακή επίγνωση του κοινωνικού πλαισίου"),
  Q("Ποιο είναι, κατά τη γλωσσολόγο, το μεγαλύτερο εμπόδιο στη διατήρηση της γλώσσας της οικογένειας;", ["Η δυσκολία της γραμματικής", "Το ότι η γλώσσα δεν έχει κύρος στο σχολείο ή στη γειτονιά", "Η έλλειψη βιβλίων", "Η ηλικία των γονιών"], 1, "Όταν η γλώσσα της οικογένειας δεν έχει κύρος στο σχολείο ή στη γειτονιά"),
 ],
 "gloss": {"δίγλωσσων": "δίγλωσσος — bilingual", "θα το μπερδέψουν": "μπερδεύω — to confuse", "διαδεδομένους": "διαδεδομένος — widespread", "αναπτυξιακά": "αναπτυξιακός — developmental", "μονόγλωσσα": "μονόγλωσσος — monolingual", "σύγχυσης": "σύγχυση — confusion", "εναλλαγή κωδίκων": "εναλλαγή κωδίκων — code-switching", "εκλεπτυσμένη": "εκλεπτυσμένος — sophisticated", "συνομιλητές": "συνομιλητής — interlocutor", "επίγνωση": "επίγνωση — awareness", "πλαισίου": "πλαίσιο — context, framework", "γνωστικό": "γνωστικός — cognitive", "κύρος": "κύρος — prestige", "εφηβεία": "εφηβεία — adolescence", "επιβιώνει": "επιβιώνω — to survive"},
})

rnd = random.Random(43)  # spread the right answers over the four positions (the page shows options in file order)
for it in ITEMS:
    for q in it["questions"]: rnd.shuffle(q["options"])
for it in ITEMS:
    for q in it["questions"]: assert q["answer"] in q["options"], (it["id"], q["q"])
    for k in it["gloss"]:
        if not (any(k in s["el"] for s in it["script"]) or k in it["context_el"]): raise SystemExit(f"gloss key not in text: {it['id']} {k}")
root = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
with open(os.path.join(root, "library", "listening", "listening-43.json"), "w", encoding="utf-8") as fh:
    json.dump({"items": ITEMS}, fh, ensure_ascii=False, indent=1); fh.write("\n")
print(len(ITEMS), "items,", sum(len(i["questions"]) for i in ITEMS), "questions")
